xml.Script:
        include 'Figures\Scripts\Dodecahedron_Coordinates.inc';
        mAngle := ArcTan(2);   // phi := (Sqrt(5) - 1) / 2; // The golden ratio
        ss := sin(mAngle / 2); // ss := phi / sqrt(2 - phi);
        cs := cos(mAngle / 2); // cs := 1 / sqrt(2 - phi);

        K := 0.6;

        Colors[ 0] := 'FFFFFF'; // clWhite
        Colors[ 1] := 'FFFF00'; // clYellow
        Colors[ 2] := '0000CC'; // clBlue
        Colors[ 3] := 'FF0000'; // clRed
        Colors[ 4] := '00AA00'; // clGreen
        Colors[ 5] := '800080'; // clViolett
        Colors[ 6] := 'FFFFAA'; // clCream
        Colors[ 7] := '0066CC'; // clLightBlue
        Colors[ 8] := 'FF6000'; // clOrange
        Colors[ 9] := '00FF00'; // clLightGreen
        Colors[10] := 'FF88CC'; // clLightViolett
        Colors[11] := '666666'; // clGray

        // Rotate p around normalized v
        procedure RotatePoint(Xp, Yp, Zp, Xv, Yv, Zv, Angle);
        begin
            ca := Cos(Angle);
            sa := Sin(Angle);
            c2 := 1 - ca;

            px[i] := Xp * (Xv * c2 * Xv + ca) +
                     Yp * (Yv * c2 * Xv - sa * Zv) +
                     Zp * (Zv * c2 * Xv + sa * Yv);

            py[i] := Xp * (Xv * c2 * Yv + sa * Zv) +
                     Yp * (Yv * c2 * Yv + ca) +
                     Zp * (Zv * c2 * Yv - sa * Xv);

            pz[i] := Xp * (Xv * c2 * Zv - sa * Yv) +
                     Yp * (Yv * c2 * Zv + sa * Xv) +
                     Zp * (Zv * c2 * Zv + ca);
            Inc(i);
        end;

        i := 0;
        RotatePoint ( 1, 0, 0,  0,-cs,-ss, 1*pi/10);
        RotatePoint (-1, 0, 0,  0,-cs,-ss, 3*pi/10);
        RotatePoint ( 1, 0, 0,  0,-cs,-ss, 5*pi/10);
        RotatePoint (-1, 0, 0,  0,-cs,-ss, 7*pi/10);
        RotatePoint ( 1, 0, 0,  0,-cs,-ss, 9*pi/10);
        RotatePoint (-1, 0, 0,  0,-cs, ss, 1*pi/10);
        RotatePoint ( 1, 0, 0,  0,-cs, ss, 3*pi/10);
        RotatePoint (-1, 0, 0,  0,-cs, ss, 5*pi/10);
        RotatePoint ( 1, 0, 0,  0,-cs, ss, 7*pi/10);
        RotatePoint (-1, 0, 0,  0,-cs, ss, 9*pi/10);
        RotatePoint ( 0, 1, 0,  -ss,0,-cs, 1*pi/10);
        RotatePoint ( 0,-1, 0,  -ss,0,-cs, 3*pi/10);
        RotatePoint ( 0, 1, 0,  -ss,0,-cs, 5*pi/10);
        RotatePoint ( 0,-1, 0,  -ss,0,-cs, 7*pi/10);
        RotatePoint ( 0, 1, 0,  -ss,0,-cs, 9*pi/10);
        RotatePoint ( 0,-1, 0,   ss,0,-cs, 1*pi/10);
        RotatePoint ( 0, 1, 0,   ss,0,-cs, 3*pi/10);
        RotatePoint ( 0,-1, 0,   ss,0,-cs, 5*pi/10);
        RotatePoint ( 0, 1, 0,   ss,0,-cs, 7*pi/10);
        RotatePoint ( 0,-1, 0,   ss,0,-cs, 9*pi/10);
        RotatePoint ( 0, 0,-1,   cs,-ss,0, 1*pi/10);
        RotatePoint ( 0, 0, 1,   cs,-ss,0, 3*pi/10);
        RotatePoint ( 0, 0,-1,   cs,-ss,0, 5*pi/10);
        RotatePoint ( 0, 0, 1,   cs,-ss,0, 7*pi/10);
        RotatePoint ( 0, 0,-1,   cs,-ss,0, 9*pi/10);
        RotatePoint ( 0, 0, 1,   cs, ss,0, 1*pi/10);
        RotatePoint ( 0, 0,-1,   cs, ss,0, 3*pi/10);
        RotatePoint ( 0, 0, 1,   cs, ss,0, 5*pi/10);
        RotatePoint ( 0, 0,-1,   cs, ss,0, 7*pi/10);
        RotatePoint ( 0, 0, 1,   cs, ss,0, 9*pi/10);

        D := K * 1.0028680188979 * py[10]; // C71*py[10]
